CREATE TABLE IF NOT EXISTS "oa_announcement" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "title" varchar(255),
    "content" varchar(255),
    "category" varchar(255),
    "priority" int,
    "publisher_user_id" bigint,
    "publisher_name" varchar(255),
    "target_scope" varchar(255),
    "publish_time" timestamp,
    "expire_time" timestamp,
    "top_flag" bit,
    "status" int,
    "view_count" int,
    "remark" varchar(255),
    "creator" varchar(64) DEFAULT '',
    "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) DEFAULT '',
    "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE,
    "tenant_id" bigint NOT NULL DEFAULT '0',
    PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS "oa_approval_template" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "code" varchar(255),
    "name" varchar(255),
    "category" varchar(255),
    "process_definition_key" varchar(255),
    "form_schema" varchar(255),
    "form_ui_schema" varchar(255),
    "description" varchar(255),
    "icon" varchar(255),
    "sort" int,
    "status" int,
    "usage_count" int,
    "creator" varchar(64) DEFAULT '',
    "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) DEFAULT '',
    "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE,
    "tenant_id" bigint NOT NULL DEFAULT '0',
    PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS "oa_document" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "no" varchar(255),
    "title" varchar(255),
    "document_type" int,
    "urgency" int,
    "confidentiality" int,
    "issuer_user_id" bigint,
    "issue_dept_id" bigint,
    "issue_date" date,
    "content" varchar(255),
    "process_instance_id" varchar(255),
    "status" int,
    "reviewer_user_id" bigint,
    "reviewer_name" varchar(255),
    "review_time" timestamp,
    "review_opinion" varchar(255),
    "signer_user_id" bigint,
    "signer_name" varchar(255),
    "sign_time" timestamp,
    "sign_opinion" varchar(255),
    "archiver_user_id" bigint,
    "archiver_name" varchar(255),
    "archive_time" timestamp,
    "archive_no" varchar(255),
    "main_send_depts" varchar(255),
    "copy_send_depts" varchar(255),
    "read_count" int,
    "remark" varchar(255),
    "creator" varchar(64) DEFAULT '',
    "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) DEFAULT '',
    "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE,
    "tenant_id" bigint NOT NULL DEFAULT '0',
    PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS "oa_document_attachment" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "document_id" bigint,
    "file_name" varchar(255),
    "file_url" varchar(255),
    "file_size" bigint,
    "file_type" varchar(255),
    "creator" varchar(64) DEFAULT '',
    "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) DEFAULT '',
    "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE,
    "tenant_id" bigint NOT NULL DEFAULT '0',
    PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS "oa_knowledge_article" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "category_id" bigint,
    "title" varchar(255),
    "summary" varchar(255),
    "content" varchar(255),
    "tags" varchar(255),
    "author_user_id" bigint,
    "author_name" varchar(255),
    "view_count" int,
    "like_count" int,
    "comment_count" int,
    "current_version" int,
    "status" int,
    "top_flag" bit,
    "remark" varchar(255),
    "creator" varchar(64) DEFAULT '',
    "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) DEFAULT '',
    "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE,
    "tenant_id" bigint NOT NULL DEFAULT '0',
    PRIMARY KEY ("id")
);

